#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>
#include "app.h"
static void flushline(void){int c;while((c=getchar())!='\n'&&c!=EOF){}}
static int line(const char*p,char*b,size_t n){printf("%s",p);if(!fgets(b,n,stdin))return 0;char*q=strchr(b,'\n');if(q)*q=0;else flushline();return b[0]!=0;}
static int integer(const char*p,int*out){char b[64],x;if(!line(p,b,sizeof b))return 0;return sscanf(b,"%d %c",out,&x)==1;}
static int realnum(const char*p,float*out){char b[64],x;if(!line(p,b,sizeof b))return 0;return sscanf(b,"%f %c",out,&x)==1;}
static int yesno(const char*p){char b[8];return line(p,b,sizeof b)&&(b[0]=='y'||b[0]=='Y');}
static int validIdText(const char*s){if(!s[0])return 0;for(;*s;s++)if(!isalnum((unsigned char)*s)&&*s!='-'&&*s!='_')return 0;return 1;}
static int rewriteStudent(const Student*updated){FILE*in=fopen(STUDENT_FILE,"rb"),*out=fopen("data/students.tmp","wb");if(!in||!out){if(in)fclose(in);if(out)fclose(out);return 0;}Student s;int ok=1;while(fread(&s,sizeof s,1,in)==1){if(!strcmp(s.studentId,updated->studentId))s=*updated;if(fwrite(&s,sizeof s,1,out)!=1){ok=0;break;}}fclose(in);fclose(out);if(!ok){remove("data/students.tmp");return 0;}remove(STUDENT_FILE);return rename("data/students.tmp",STUDENT_FILE)==0;}
void studentMenu(void){for(;;){int c;if(!integer("\nSTUDENT MANAGEMENT\n1 Add  2 View  3 Search  4 Update  5 Delete  6 Back\nChoice: ",&c))continue;if(c==6)return;if(c==1){Student s={0};generateStudentId(s.studentId);printf("Generated ID: %s\n",s.studentId);if(!line("Roll: ",s.rollNumber,sizeof s.rollNumber)||rollExists(s.rollNumber)||!line("Name: ",s.name,sizeof s.name)||!line("Branch: ",s.branch,sizeof s.branch)){puts("Invalid or duplicate data.");continue;}puts(saveStudent(&s)?"Student saved.":"Save failed.");}else if(c==2){FILE*f=fopen(STUDENT_FILE,"rb");Student s;puts("ID        ROLL        NAME                         BRANCH");if(!f){puts("No students.");continue;}while(fread(&s,sizeof s,1,f)==1)printf("%-9s %-11s %-28s %s\n",s.studentId,s.rollNumber,s.name,s.branch);fclose(f);}else if(c==3){char id[MAX_ID_LENGTH];Student s;if(line("Student ID: ",id,sizeof id)&&findStudentById(id,&s))printf("%s | %s | %s | %s\n",s.studentId,s.rollNumber,s.name,s.branch);else puts("Student not found.");}else if(c==4){char id[MAX_ID_LENGTH];Student s;if(!line("Student ID to update: ",id,sizeof id)||!findStudentById(id,&s)){puts("Student not found.");continue;}char roll[MAX_ROLL_LENGTH],name[MAX_NAME_LENGTH],branch[MAX_BRANCH_LENGTH];printf("Current: %s | %s | %s\n",s.rollNumber,s.name,s.branch);if(!line("New roll: ",roll,sizeof roll)||(!strcmp(roll,s.rollNumber)?0:rollExists(roll))||!line("New name: ",name,sizeof name)||!line("New branch: ",branch,sizeof branch)){puts("Invalid or duplicate update.");continue;}strcpy(s.rollNumber,roll);strcpy(s.name,name);strcpy(s.branch,branch);puts(rewriteStudent(&s)?"Student updated.":"Update failed.");}else if(c==5){char id[MAX_ID_LENGTH];if(!line("Student ID to delete: ",id,sizeof id)||!studentIdExists(id)){puts("Student not found.");continue;}puts("This also removes the student's marks and calculated results.");if(!yesno("Continue? (Y/N): ")){puts("Deletion cancelled.");continue;}puts(deleteStudentCascade(id)?"Student and related academic records deleted.":"Deletion failed.");}else puts("Invalid choice.");}}
void subjectMenu(void){for(;;){int c;if(!integer("\nSUBJECT MANAGEMENT\n1 Add  2 View  3 Back\nChoice: ",&c))continue;if(c==3)return;if(c==1){Subject s={0};if(!line("Code: ",s.subjectCode,sizeof s.subjectCode)||!validIdText(s.subjectCode)||findSubject(s.subjectCode,NULL)||!line("Name: ",s.subjectName,sizeof s.subjectName)||!line("Comparison group: ",s.comparisonGroup,sizeof s.comparisonGroup)||!integer("Semester: ",&s.semester)||s.semester<1||s.semester>MAX_SEMESTERS||!realnum("Maximum marks: ",&s.maximumMarks)||s.maximumMarks<=0||!realnum("Passing marks: ",&s.passingMarks)||s.passingMarks<0||s.passingMarks>s.maximumMarks){puts("Invalid or duplicate subject data.");continue;}puts(saveSubject(&s)?"Subject saved.":"Save failed.");}else if(c==2){FILE*f=fopen(SUBJECT_FILE,"rb");Subject s;if(!f){puts("No subjects.");continue;}puts("CODE       SUBJECT                       GROUP        SEM  MAX   PASS");while(fread(&s,sizeof s,1,f)==1)printf("%-10s %-29s %-12s %-4d %-5.1f %.1f\n",s.subjectCode,s.subjectName,s.comparisonGroup,s.semester,s.maximumMarks,s.passingMarks);fclose(f);}else puts("Invalid choice.");}}
static int updateMarkRecord(const char*id,const char*code,int sem,float value){FILE*in=fopen(MARKS_FILE,"rb"),*out=fopen("data/marks.tmp","wb");if(!in||!out){if(in)fclose(in);if(out)fclose(out);return 0;}MarkRecord m;int found=0,ok=1;while(fread(&m,sizeof m,1,in)==1){if(!strcmp(m.studentId,id)&&!strcmp(m.subjectCode,code)&&m.semester==sem){m.marksObtained=value;found=1;}if(fwrite(&m,sizeof m,1,out)!=1){ok=0;break;}}fclose(in);fclose(out);if(!ok||!found){remove("data/marks.tmp");return 0;}remove(MARKS_FILE);if(rename("data/marks.tmp",MARKS_FILE)!=0)return 0;return invalidateResult(id,sem);}
void marksMenu(void){for(;;){int c;if(!integer("\nMARKS MANAGEMENT\n1 Enter  2 View  3 Update  4 Back\nChoice: ",&c))continue;if(c==4)return;if(c==1){MarkRecord m={0};Subject s;if(!line("Student ID: ",m.studentId,sizeof m.studentId)||!studentIdExists(m.studentId)||!integer("Semester: ",&m.semester)||m.semester<1||m.semester>MAX_SEMESTERS||!line("Subject code: ",m.subjectCode,sizeof m.subjectCode)||!findSubject(m.subjectCode,&s)||s.semester!=m.semester||markExists(m.studentId,m.subjectCode,m.semester)||!realnum("Marks: ",&m.marksObtained)||m.marksObtained<0||m.marksObtained>s.maximumMarks){puts("Invalid, duplicate, or inconsistent marks record.");continue;}puts(saveMark(&m)?"Marks saved.":"Save failed.");}else if(c==2){char id[MAX_ID_LENGTH];int sem;if(!line("Student ID: ",id,sizeof id)||!integer("Semester: ",&sem))continue;FILE*f=fopen(MARKS_FILE,"rb");MarkRecord m;Subject s;int n=0;if(f){while(fread(&m,sizeof m,1,f)==1)if(!strcmp(m.studentId,id)&&m.semester==sem&&findSubject(m.subjectCode,&s)){printf("%-10s %-25s %.2f/%.2f\n",s.subjectCode,s.subjectName,m.marksObtained,s.maximumMarks);n++;}fclose(f);}if(!n)puts("No marks found.");}else if(c==3){char id[MAX_ID_LENGTH],code[MAX_SUBJECT_CODE];int sem;float v;Subject s;if(!line("Student ID: ",id,sizeof id)||!integer("Semester: ",&sem)||!line("Subject code: ",code,sizeof code)||!findSubject(code,&s)||!markExists(id,code,sem)||!realnum("New marks: ",&v)||v<0||v>s.maximumMarks){puts("Invalid update.");continue;}puts(updateMarkRecord(id,code,sem,v)?"Marks updated; old calculated result invalidated.":"Update failed.");}else puts("Invalid choice.");}}
void calculateResult(void){char id[MAX_ID_LENGTH];int sem;if(!line("Student ID: ",id,sizeof id)||!studentIdExists(id)||!integer("Semester: ",&sem)||sem<1||sem>MAX_SEMESTERS){puts("Invalid student/semester.");return;}FILE*sf=fopen(SUBJECT_FILE,"rb");if(!sf){puts("No subjects.");return;}Subject s;int required=0,found=0,failed=0;float got=0,max=0;while(fread(&s,sizeof s,1,sf)==1)if(s.semester==sem){required++;FILE*mf=fopen(MARKS_FILE,"rb");MarkRecord m;int ok=0;if(mf){while(fread(&m,sizeof m,1,mf)==1)if(!strcmp(m.studentId,id)&&!strcmp(m.subjectCode,s.subjectCode)&&m.semester==sem){ok=1;found++;got+=m.marksObtained;max+=s.maximumMarks;if(m.marksObtained<s.passingMarks)failed=1;break;}fclose(mf);}if(!ok)printf("Missing: %s - %s\n",s.subjectCode,s.subjectName);}fclose(sf);if(!required||found!=required){printf("Incomplete record (%d/%d subjects). Result not finalized.\n",found,required);return;}SemesterResult r={0};strcpy(r.studentId,id);r.semester=sem;r.totalMarksObtained=got;r.totalMaximumMarks=max;r.percentage=percentage(got,max);getGrade(r.percentage,r.overallGrade);r.passed=!failed;if(upsertResult(&r))printf("Result: %.2f/%.2f | %.2f%% | %s | %s\n",got,max,r.percentage,r.overallGrade,r.passed?"PASS":"FAIL");else puts("Could not save result.");}
typedef struct{Subject s;float p;float marks;} WeakRow;static int weakCmp(const void*a,const void*b){float d=((const WeakRow*)a)->p-((const WeakRow*)b)->p;return d>0?1:d<0?-1:0;}
void weakAnalysis(void){char id[MAX_ID_LENGTH];int sem;if(!line("Student ID: ",id,sizeof id)||!studentIdExists(id)||!integer("Semester: ",&sem))return;float t=weakThreshold();FILE*f=fopen(MARKS_FILE,"rb");MarkRecord m;WeakRow rows[MAX_SUBJECTS];int n=0;if(!f){puts("No marks.");return;}while(fread(&m,sizeof m,1,f)==1)if(!strcmp(m.studentId,id)&&m.semester==sem&&n<MAX_SUBJECTS){Subject s;if(findSubject(m.subjectCode,&s)){float p=percentage(m.marksObtained,s.maximumMarks);if(p<t||m.marksObtained<s.passingMarks){rows[n].s=s;rows[n].p=p;rows[n].marks=m.marksObtained;n++;}}}fclose(f);qsort(rows,(size_t)n,sizeof rows[0],weakCmp);printf("Weak threshold: %.2f%%\n",t);for(int i=0;i<n;i++){float gap=t-rows[i].p;const char*priority=gap>=20?"CRITICAL":gap>=10?"HIGH":"MODERATE";printf("%d. %s: %.2f%% | %s | %s\n",i+1,rows[i].s.subjectName,rows[i].p,priority,rows[i].marks<rows[i].s.passingMarks?"below pass requirement":"below improvement threshold");}if(!n)puts("No weak subjects detected.");}
void rankingMenu(void){int sem;if(!integer("Semester: ",&sem))return;RankingRecord a[MAX_STUDENTS];int n=buildRanking(sem,a,MAX_STUDENTS);if(!n){puts("No results.");return;}puts("RANK  ID        NAME                         %      STATUS");for(int i=0;i<n;i++)printf("%-5d %-9s %-28s %6.2f %s\n",a[i].rank,a[i].studentId,a[i].studentName,a[i].percentage,a[i].passed?"PASS":"FAIL");puts("\nTOP FIVE RECORDS");for(int i=0;i<n&&i<5;i++)printf("%d. %s - %.2f%% (Rank %d)\n",i+1,a[i].studentName,a[i].percentage,a[i].rank);}
void analyticsMenu(void){int sem;if(!integer("Semester: ",&sem))return;FILE*f=fopen(RESULT_FILE,"rb");SemesterResult r;int n=0,pass=0;float sum=0,hi=-1,lo=101;if(f){while(fread(&r,sizeof r,1,f)==1)if(r.semester==sem){n++;sum+=r.percentage;if(r.passed)pass++;if(r.percentage>hi)hi=r.percentage;if(r.percentage<lo)lo=r.percentage;}fclose(f);}if(!n){puts("No results.");return;}printf("Students: %d | Average: %.2f%% | Highest: %.2f%% | Lowest: %.2f%% | Pass: %.2f%% | Fail: %.2f%%\n",n,sum/n,hi,lo,100.0f*pass/n,100.0f*(n-pass)/n);puts("\nSUBJECT ANALYTICS");FILE*sf=fopen(SUBJECT_FILE,"rb");Subject s;if(sf){while(fread(&s,sizeof s,1,sf)==1)if(s.semester==sem){FILE*mf=fopen(MARKS_FILE,"rb");MarkRecord m;int count=0,ps=0,fl=0;float total=0;if(mf){while(fread(&m,sizeof m,1,mf)==1)if(m.semester==sem&&!strcmp(m.subjectCode,s.subjectCode)){count++;total+=m.marksObtained;if(m.marksObtained>=s.passingMarks)ps++;else fl++;}fclose(mf);}if(count)printf("%-25s avg %.2f%% | pass %d | fail %d | records %d\n",s.subjectName,percentage(total/count,s.maximumMarks),ps,fl,count);}fclose(sf);}}
static int findGroupMark(const char*id,int sem,const char*group,Subject*outS,float*outP){FILE*sf=fopen(SUBJECT_FILE,"rb");if(!sf)return 0;Subject s;while(fread(&s,sizeof s,1,sf)==1)if(s.semester==sem&&!strcmp(s.comparisonGroup,group)){FILE*mf=fopen(MARKS_FILE,"rb");MarkRecord m;if(mf){while(fread(&m,sizeof m,1,mf)==1)if(!strcmp(m.studentId,id)&&m.semester==sem&&!strcmp(m.subjectCode,s.subjectCode)){if(outS)*outS=s;if(outP)*outP=percentage(m.marksObtained,s.maximumMarks);fclose(mf);fclose(sf);return 1;}fclose(mf);}}fclose(sf);return 0;}
void compareSemesters(void){char id[MAX_ID_LENGTH];int a,b;SemesterResult x,y;if(!line("Student ID: ",id,sizeof id)||!integer("Previous semester: ",&a)||!integer("Current semester: ",&b)||a==b||!findResult(id,a,&x)||!findResult(id,b,&y)){puts("Comparison unavailable.");return;}float d=y.percentage-x.percentage;printf("Semester %d: %.2f%% | Semester %d: %.2f%% | Change: %+.2f percentage points | %s\n",a,x.percentage,b,y.percentage,d,d>0.001?"IMPROVED":d<-0.001?"DECLINED":"UNCHANGED");puts("Comparable subject groups:");FILE*sf=fopen(SUBJECT_FILE,"rb");Subject s;char seen[MAX_SUBJECTS][MAX_SUBJECT_CODE];int ns=0;if(sf){while(fread(&s,sizeof s,1,sf)==1)if(s.semester==a&&s.comparisonGroup[0]){int dup=0;for(int i=0;i<ns;i++)if(!strcmp(seen[i],s.comparisonGroup))dup=1;if(!dup&&ns<MAX_SUBJECTS){strcpy(seen[ns++],s.comparisonGroup);Subject sa,sb;float pa,pb;if(findGroupMark(id,a,s.comparisonGroup,&sa,&pa)&&findGroupMark(id,b,s.comparisonGroup,&sb,&pb))printf("%-12s %-22s %.2f%% -> %-22s %.2f%% (%+.2f pp)\n",s.comparisonGroup,sa.subjectName,pa,sb.subjectName,pb,pb-pa);}}fclose(sf);}}
void generateReport(void){char id[MAX_ID_LENGTH];int sem;Student st;SemesterResult r;if(!line("Student ID: ",id,sizeof id)||!integer("Semester: ",&sem)||!findStudentById(id,&st)||!findResult(id,sem,&r)){puts("Finalized result not found.");return;}char path[160];snprintf(path,sizeof path,"reports/%s_Semester_%d.txt",id,sem);FILE*out=fopen(path,"w");if(!out){puts("Cannot create report.");return;}fprintf(out,"STUDENT ACADEMIC PERFORMANCE REPORT\n===================================\nStudent ID: %s\nRoll: %s\nName: %s\nBranch: %s\nSemester: %d\n\nSUBJECT PERFORMANCE\n",st.studentId,st.rollNumber,st.name,st.branch,sem);FILE*f=fopen(MARKS_FILE,"rb");MarkRecord m;Subject s;float t=weakThreshold();int weak=0;if(f){while(fread(&m,sizeof m,1,f)==1)if(!strcmp(m.studentId,id)&&m.semester==sem&&findSubject(m.subjectCode,&s)){float p=percentage(m.marksObtained,s.maximumMarks);char g[MAX_GRADE_LENGTH];getGrade(p,g);fprintf(out,"%-10s %-25s %6.2f/%6.2f %6.2f%% %s\n",s.subjectCode,s.subjectName,m.marksObtained,s.maximumMarks,p,g);if(p<t||m.marksObtained<s.passingMarks)weak++;}fclose(f);}int total=0,rank=getRank(id,sem,&total);fprintf(out,"\nOVERALL\nTotal: %.2f/%.2f\nPercentage: %.2f%%\nGrade: %s\nStatus: %s\nRank: %d/%d\nWeak subjects: %d\n",r.totalMarksObtained,r.totalMaximumMarks,r.percentage,r.overallGrade,r.passed?"PASS":"FAIL",rank,total,weak);fprintf(out,"\nPERFORMANCE SUMMARY\nThe student achieved %.2f%% and %s the recorded subject-level passing requirements. %d subject(s) require attention under current criteria.\n",r.percentage,r.passed?"satisfied":"did not satisfy",weak);if(sem>1){SemesterResult p;if(findResult(id,sem-1,&p)){float d=r.percentage-p.percentage;fprintf(out,"Trend from semester %d: %+.2f percentage points (%s)\n",sem-1,d,d>0.001?"IMPROVED":d<-0.001?"DECLINED":"UNCHANGED");}}fclose(out);printf("Report saved: %s\n",path);}
static int countFile(const char*path,size_t sz){FILE*f=fopen(path,"rb");if(!f)return 0;if(fseek(f,0,SEEK_END)!=0){fclose(f);return 0;}long n=ftell(f);fclose(f);return n<0?0:(int)(n/(long)sz);}
void dashboard(void){printf("\nACADEMIC DASHBOARD\nStudents: %d\nSubjects: %d\nResults: %d\nWeak threshold: %.2f%%\n",countFile(STUDENT_FILE,sizeof(Student)),countFile(SUBJECT_FILE,sizeof(Subject)),countFile(RESULT_FILE,sizeof(SemesterResult)),weakThreshold());}
static void changePassword(void){Admin a;FILE*f=fopen(ADMIN_FILE,"rb");if(!f||fread(&a,sizeof a,1,f)!=1){if(f)fclose(f);puts("Admin data unavailable.");return;}fclose(f);char old[MAX_PASSWORD_LENGTH],nw[MAX_PASSWORD_LENGTH];if(!line("Current password: ",old,sizeof old)||strcmp(old,a.password)){puts("Incorrect password.");return;}if(!line("New password: ",nw,sizeof nw)||strlen(nw)<4){puts("Password must contain at least 4 characters.");return;}strcpy(a.password,nw);f=fopen(ADMIN_FILE,"wb");if(!f){puts("Cannot save password.");return;}int ok=fwrite(&a,sizeof a,1,f)==1;fclose(f);puts(ok?"Password changed.":"Password change failed.");}
static void viewGrades(void){FILE*f=fopen(GRADE_FILE,"rb");GradeConfig g;if(!f){puts("No grade configuration.");return;}puts("GRADE   MIN      MAX");while(fread(&g,sizeof g,1,f)==1)printf("%-7s %-8.2f %.2f\n",g.grade,g.minimumPercentage,g.maximumPercentage);fclose(f);}
static void editGrades(void){int n;if(!integer("Number of grade bands: ",&n)||n<1||n>MAX_GRADE_CONFIGS){puts("Invalid count.");return;}GradeConfig g[MAX_GRADE_CONFIGS];for(int i=0;i<n;i++){printf("Band %d\n",i+1);if(!line("Grade label: ",g[i].grade,sizeof g[i].grade)||!realnum("Minimum: ",&g[i].minimumPercentage)||!realnum("Maximum: ",&g[i].maximumPercentage)){puts("Invalid input.");return;}}if(!validateGrades(g,n)){puts("Invalid ranges: grade bands must cover 0 to 100 exactly with no gaps or overlaps.");return;}puts("Changing grades invalidates all saved calculated results.");if(!yesno("Continue? (Y/N): "))return;puts(saveGrades(g,n)?"Grade configuration saved; results invalidated.":"Save failed.");}
void settingsMenu(void){for(;;){int c;if(!integer("\nSYSTEM SETTINGS\n1 View grades\n2 Edit grades\n3 Change weak threshold\n4 Change password\n5 Backup academic data\n6 Restore academic data\n7 Back\nChoice: ",&c))continue;if(c==7)return;if(c==1)viewGrades();else if(c==2)editGrades();else if(c==3){float t;if(realnum("New threshold (0-100): ",&t))puts(setWeakThreshold(t)?"Threshold updated.":"Invalid threshold.");}else if(c==4)changePassword();else if(c==5)puts(backupData()?"Backup completed.":"Backup failed.");else if(c==6){puts("WARNING: restore replaces current academic data with backup copies.");if(yesno("Continue? (Y/N): "))puts(restoreData()?"Restore completed.":"Restore failed.");}else puts("Invalid choice.");}}
void mainMenu(void){for(;;){int c;if(!integer("\n=== STUDENT RESULT & GRADE ANALYZER ===\n1 Students\n2 Subjects\n3 Marks\n4 Calculate Result\n5 Weak Analysis\n6 Ranking\n7 Analytics\n8 Semester Comparison\n9 Generate Report\n10 Dashboard\n11 Settings\n12 Logout\nChoice: ",&c))continue;switch(c){case 1:studentMenu();break;case 2:subjectMenu();break;case 3:marksMenu();break;case 4:calculateResult();break;case 5:weakAnalysis();break;case 6:rankingMenu();break;case 7:analyticsMenu();break;case 8:compareSemesters();break;case 9:generateReport();break;case 10:dashboard();break;case 11:settingsMenu();break;case 12:return;default:puts("Invalid choice.");}}}
